            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x6E7EF383BA6B5722ULL) + aOrbiterUpdateSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xB38B1C09BB092864ULL;
