            aWandererF = aWandererF + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterK, 11U)) + aOrbiterJ) + aNonceWordO);
            aWandererD = aWandererD ^ ((((RotL64(aCross, 19U) + RotL64(aOrbiterG, 41U)) + aOrbiterD) + aNonceWordG) + aWandererUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1]);
