            aOrbiterD = (((aWandererI + RotL64(aScatter, 28U)) + RotL64(aCarry, 3U)) + 0x93E435E93C6A26BFULL) + aOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
