            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0x7845AED35720EF84ULL) + aNonceWordP;
            aOrbiterH = (((aOrbiterH ^ aOrbiterK) ^ 0xE137C5AB33F5F5A8ULL) ^ aOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1]) ^ aNonceWordI;
            aOrbiterH = RotL64((aOrbiterH * 0x7C774B464F5E2D0BULL), 19U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterK) + 0xD4621B563E4BCBC1ULL) + aOrbiterUpdateSaltE[((aIndex + 10U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0xBAC6239CF980DF69ULL) ^ aNonceWordB;
            aOrbiterJ = RotL64((aOrbiterJ * 0xE85F2E1D4D1D3C35ULL), 47U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x7B4C30E8B8A02905ULL) + aNonceWordO;
