            aWandererB = aWandererB ^ (((RotL64(aCross, 39U) + aOrbiterE) + RotL64(aOrbiterI, 23U)) + aNonceWordG);
            aWandererE = aWandererE + (((RotL64(aScatter, 21U) + RotL64(aOrbiterK, 4U)) + aOrbiterI) + RotL64(aCarry, 35U));
