            aIngress ^= (RotL64(aWindLaneB[((aIndex + 12189U)) & S_BLOCK1], 5U) ^ RotL64(aFireLaneC[((aIndex + 15917U)) & S_BLOCK1], 39U));
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aDomainWordIngress) ^ aNonceWordL));
