            aCross = (RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 15242U)) & S_BLOCK1], 53U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 14575U)) & S_BLOCK1], 44U));
