            aIngress ^= (RotL64(aFireLaneA[((aIndex + 10569U)) & S_BLOCK1], 57U) ^ RotL64(aSpiritLaneC[((S_BLOCK1 - aIndex + 11308U)) & S_BLOCK1], 19U));
