            //
            aOrbiterG = (aWandererH + RotL64(aCross, 27U)) + 0x92F5872AA04EF432ULL;
            aOrbiterD = (((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 5U)) + 0xBDD566686D7E79A5ULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 51U)) + 0xB8AEEBCCFE87025CULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 13U)) & S_SALT1];
