            aOrbiterJ = (aWandererB + RotL64(aIngress, 37U)) + 0x3FA1B7AA8A05AF14ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0x1A4C93B8732C3F92ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x1ABA1353A2DEE5BCULL;
            aOrbiterK = RotL64((aOrbiterK * 0x37EF235A9A82D985ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xBB2734DB4AD03AC8ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xAF1C22F83DA8E5A1ULL;
