            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCross, 19U) ^ RotL64(aPrevious, 44U)) ^ (RotL64(aIngress, 57U) + RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterF = ((aWandererC + RotL64(aIngress, 10U)) + RotL64(aCarry, 27U)) + 0x959EC37F0F1BA04BULL;
            aOrbiterG = (aWandererB + RotL64(aScatter, 43U)) + 0x584F74170A6D50E1ULL;
            aOrbiterJ = ((aWandererK + RotL64(aCross, 51U)) + RotL64(aCarry, 5U)) + 0x03965458305AA0DAULL;
            aOrbiterK = ((aWandererA + RotL64(aPrevious, 35U)) + 0xE6D212B9D8BBA358ULL) + aPhaseAOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterH = (aWandererE + RotL64(aIngress, 3U)) + 0x4B895366443C69D7ULL;
            aOrbiterC = (((aWandererD + RotL64(aPrevious, 27U)) + RotL64(aCarry, 51U)) + 0x6B29F039A83DD681ULL) + aPhaseAOrbiterAssignSaltF[((aIndex + 19U)) & S_SALT1];
            aOrbiterB = (aWandererJ + RotL64(aScatter, 19U)) + 0x8F998FBAD9EF1344ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x591EF7F167C1B551ULL) + aPhaseAOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
