            aOrbiterB = RotL64((aOrbiterB * 0xB27939182A1BD841ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x67EF856A366CD9F9ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0xA42F056ACD37C553ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9131C259BBC60A21ULL), 41U);
